// test_rice_crc.c — the C key must equal the reference implementation.
//
// Vectors generated from tools/ricepack/rice_crc.py at its DEFAULT_VARIANT
// (rice-hires-swap32, the reading measured against a real ROM and a real pack
// on 2026-09-08). They cover every RDP size code, an odd width, a pitch wider
// than a row, and the smallest geometry the key is defined over.
//
// If the two implementations ever disagree, shipped packs stop resolving while
// the offline importer keeps working -- a split that would be very hard to see
// from either side alone. So they are held to the same numbers here.
#include "rice_crc.h"

#include <stdio.h>
#include <limits.h>

static int failures = 0;

static void expect(int condition, const char *message) {
    if (!condition) { printf("FAIL: %s\n", message); ++failures; }
}

