static const unsigned char kData8[] = {191,82,177,22,45,132,90,149,246,192,237,131,189,146,95,189,174,50,19,252,46,211,209,184,136,26,108,100,154,152,101,102};

int main(void) {
    uint32_t key = 0;
    expect(mdkr_rice_crc32(kData0, sizeof kData0, 32, 32, 2, 64, &key) == 1,
           "vector 0 is accepted");
    expect(key == 0x5EEF431Au, "vector 0 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData1, sizeof kData1, 64, 32, 2, 128, &key) == 1,
           "vector 1 is accepted");
    expect(key == 0x580491C2u, "vector 1 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData2, sizeof kData2, 16, 16, 0, 8, &key) == 1,
           "vector 2 is accepted");
    expect(key == 0x5DB20F2Bu, "vector 2 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData3, sizeof kData3, 8, 8, 1, 8, &key) == 1,
           "vector 3 is accepted");
    expect(key == 0x1AE32EE4u, "vector 3 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData4, sizeof kData4, 32, 32, 3, 128, &key) == 1,
           "vector 4 is accepted");
    expect(key == 0x472E2DD4u, "vector 4 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData5, sizeof kData5, 37, 11, 2, 74, &key) == 1,
           "vector 5 is accepted");
    expect(key == 0xEA8E84C9u, "vector 5 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData6, sizeof kData6, 32, 32, 2, 160, &key) == 1,
           "vector 6 is accepted");
    expect(key == 0xBC8F7AFAu, "vector 6 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData7, sizeof kData7, 64, 64, 1, 96, &key) == 1,
           "vector 7 is accepted");
    expect(key == 0x5F05EF40u, "vector 7 matches rice_crc.py");
    expect(mdkr_rice_crc32(kData8, sizeof kData8, 4, 4, 2, 8, &key) == 1,
           "vector 8 is accepted");
    expect(key == 0x6EE59CDEu, "vector 8 matches rice_crc.py");

    /* Refusals. A keying function that answers for a span it does not hold
     * names the wrong picture in silence, which is worse than no answer. */
    expect(mdkr_rice_crc32(kData0, sizeof kData0, 32, 32, 7, 0, &key) == 0,
           "an undefined RDP size code is refused");
    expect(mdkr_rice_crc32(kData0, sizeof kData0, 0, 32, 2, 0, &key) == 0,
           "a zero width is refused");
    expect(mdkr_rice_crc32(kData0, sizeof kData0, 32, 32, 2, 8, &key) == 0,
           "a pitch narrower than a row is refused");
    expect(mdkr_rice_crc32(kData0, 16, 32, 32, 2, 0, &key) == 0,
           "a span too short for the walk is refused");
    expect(mdkr_rice_crc32(kData0, sizeof kData0, 4, 4, 0, 0, &key) == 0,
           "a row shorter than one accumulator read is refused");

    key = 0x12345678u;
    expect(!mdkr_rice_crc32(kData0, sizeof kData0, INT_MAX, 1, 3, 0, &key) &&
               key == 0x12345678u,
           "huge row refuses without signed-long overflow or output mutation");
    expect(!mdkr_rice_crc32(kData0, sizeof kData0, 8, INT_MAX, 1, INT_MAX, &key) &&
               key == 0x12345678u,
           "huge pitched span refuses before multiplying dimensions");
    const uint8_t odd_row[] = {0, 1, 2, 3, 4};
    expect(mdkr_rice_crc32(odd_row, sizeof odd_row, 5, 1, 1, 0, &key) && key == 0x0204060Au,
           "non-DWORD row preserves final backward accumulator offset");
    expect(!mdkr_rice_crc32(odd_row, sizeof odd_row - 1, 5, 1, 1, 0, &key),
           "one-byte-short odd row refuses");

    if (failures) { printf("%d rice crc failure(s)\n", failures); return 1; }
    printf("rice crc matches the reference over 9 vectors\n");
    return 0;
}
